import{_ as a,a as t,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第三册：培养技能 · Lesson 1 A puma at large","description":"学习 定语从句与证据限定，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第三册：培养技能 · Lesson 1 A puma at large","description":"学习 定语从句与证据限定，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第3册课时","summary":"学习 定语从句与证据限定，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":false,"next":{"text":"第三册：培养技能 · Lesson 2 Thirteen equals one","link":"/life/english/new-concept/book-3/unit-01/lesson-002"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":{"text":"第三册：培养技能 · Lesson 2 Thirteen equals one","link":"/life/english/new-concept/book-3/unit-01/lesson-002"}},"headers":[],"relativePath":"life/english/new-concept/book-3/unit-01/lesson-001.md","filePath":"life/english/new-concept/book-3/unit-01/lesson-001.md"}'),r={name:"life/english/new-concept/book-3/unit-01/lesson-001.md"};function i(l,e,s,h,d,c){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第三册-培养技能-·-lesson-1-a-puma-at-large" tabindex="-1">第三册：培养技能 · Lesson 1 A puma at large <a class="header-anchor" href="#第三册-培养技能-·-lesson-1-a-puma-at-large" aria-label="Permalink to &quot;第三册：培养技能 · Lesson 1 A puma at large&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-3/contents">本册目录</a> · <a href="/life/english/new-concept/book-3/unit-01/overview">单元 1</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>从野生动物目击报告出发，训练把亲眼所见、他人转述和推测分开表达。重点不是记住某种动物的百科知识，而是识别信息来源和证据强弱，能够用一个定语从句限定对象，再用谨慎的情态表达说明尚未证实的判断。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>evidence</td><td>/ˈevɪdəns/</td><td>n.</td><td>证据</td><td>collect evidence</td></tr><tr><td>witness</td><td>/ˈwɪtnəs/</td><td>n.</td><td>目击者</td><td>a reliable witness</td></tr><tr><td>track</td><td>/træk/</td><td>n.</td><td>足迹</td><td>animal tracks</td></tr><tr><td>confirm</td><td>/kənˈfɜːm/</td><td>v.</td><td>确认</td><td>confirm a report</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>at large — 逃逸而未被抓住，常置于名词后</li><li>come to light — 信息被发现，主语通常是事实或证据</li></ul><h2 id="语法讲解-定语从句与证据限定" tabindex="-1">语法讲解：定语从句与证据限定 <a class="header-anchor" href="#语法讲解-定语从句与证据限定" aria-label="Permalink to &quot;语法讲解：定语从句与证据限定&quot;">​</a></h2><p>限定性定语从句紧跟被修饰名词，帮助读者确定说的是哪一个人或物。指物可用 which 或 that，指人可用 who 或 that；关系词在从句中作宾语时通常可以省略，作主语时不能随意删掉。逗号隔开的非限定性从句用于补充信息，不能用 that，也不能省去关系词。描述目击报告时，还要把从句中的事实与主句中的推测区分开，不能因为用了复杂句就把不确定的信息写成结论。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The tracks that we found near the gate may belong to a large dog.</p></blockquote><p>我们在门附近发现的足迹可能是一只大狗留下的。</p><p>that we found near the gate 修饰 tracks，that 作 found 的宾语；may 表示不确定推测。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>The tracks that appeared overnight 中 that 作主语，不能删；The tracks that we photographed 中 that 作宾语，可以删。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>朗读原创示范，把 tracks、camera、shadow 读成信息重音；录音后检查 may have 是否被误读成确定的过去事实。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>A student noticed fresh tracks behind the library. The camera that faces the garden recorded a shadow. It may have been a fox, but we need clearer evidence.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>用三句英语写一次尚未证实的校园动物目击报告，必须区分证据和推测。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>noticed 和 recorded 报告观察结果；may 和 but 给结论保留边界。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>把例句中的 that 省略，句子还成立吗？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 成立。</p><p><strong>解析：</strong> that 在关系从句中作 found 的宾语。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>例句能证明足迹来自狗吗？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 不能。</p><p><strong>解析：</strong> may 只表示可能。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>填空：A witness ___ lives nearby called us.（who/which）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> who</p><p><strong>解析：</strong> 先行词为人，关系词作从句主语。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：定语从句与证据限定。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-3/unit-01/grammar">单元语法</a> · <a href="/life/english/new-concept/book-3/unit-01/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-3/unit-01/review">单元自测</a></p><p><a href="/life/english/new-concept/book-3/overview">本册介绍</a> · <a href="/life/english/new-concept/book-3/unit-01/overview">单元目录</a> · <a href="/life/english/new-concept/book-3/unit-01/lesson-002">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=a(r,[["render",i]]);export{u as __pageData,b as default};
